    vector<vector<int>> permute(vector<int>& nums) {
        vector<vector<int>> res;
        vector<int> path;
        vector<bool> used(nums.size(), false);
        function<void()> dfs = [&]() {
            if (path.size() == nums.size()) {
                res.push_back(path);
                return;
            }
            for (int i = 0; i < nums.size(); i++) {
                if (used[i]) {
                    continue;
                }
                used[i] = true;
                path.push_back(nums[i]);
                dfs();
                path.pop_back();                        // 撤销选择
                used[i] = false;
            }
        };
        dfs();
        return res;
    }
};

